    표8_상담적용: [
        {"상황":"기도 응답이 늦어 지치는 분", "성경원리":"예수님도 사도들에게 기다리라고 명하셨다. 기다림은 신앙의 실패가 아니라 하나님의 때를 인정하는 성숙한 신앙이다", "실제적용":"기다리는 동안 무엇을 해야 할지 모를 때 사도들처럼 마음을 같이하여 기도하는 공동체와 함께하라"},
        {"상황":"하나님의 인도가 불분명하다고 느끼는 분", "성경원리":"하나님은 예루살렘을 떠나지 말라는 구체적 지시를 주셨다. 현재 있는 자리에서 충실하게 순종하는 것이 다음 단계로 가는 길이다", "실제적용":"지금 내가 있는 자리에서 충실하게 섬기라. 하나님의 다음 인도는 현재의 자리에서 순종할 때 나타난다"},
        {"상황":"성령 충만을 경험하지 못해 갈급한 분", "성경원리":"성령은 아버지의 약속이다. 인간의 노력이 아닌 하나님의 선물이다. 그러나 기다리며 구하는 자에게 임하신다", "실제적용":"성령 충만은 특별한 감정 경험이 아니라 말씀 앞에 순종하는 삶에서 온다. 기도와 말씀 묵상으로 하나님 앞에 자리를 지키라"}
    ],
