        {"구절":"요 14:16-17", "연결점":"내가 아버지께 구하겠으니 다른 보혜사를 주시리라 — 성령 약속", "구분":"신약"},
        {"구절":"눅 24:49", "연결점":"아버지의 약속하신 것을 너희에게 보내리라 — 동일한 약속", "구분":"신약"},
        {"구절":"사 40:31", "연결점":"여호와를 앙망하는 자는 새 힘을 얻으리니 — 기다림의 복", "구분":"구약"},
        {"구절":"출 19:1-2", "연결점":"이스라엘이 시내산 앞에 진을 치고 기다렸듯 — 기다림의 예표", "구분":"구약"},
        {"구절":"합 2:3", "연결점":"이 묵시는 정한 때가 있나니 기다리라 — 하나님의 때", "구분":"구약"},
        {"구절":"갈 4:4-6", "연결점":"때가 차매 하나님이 그 아들을 보내셨고 성령을 보내셨다", "구분":"신약"},
        {"구절":"행 2:1-4", "연결점":"오순절에 성령이 임하심 — 이 약속의 성취", "구분":"신약"}
